using System.Data;
using FIXIT.Domain;
using System.Security.Claims;
using FIXIT.API.Contracts;
using FIXIT.Domain.Entities;
using FIXIT.Infrastructure;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Hosting;
namespace FIXIT.API.Controllers;
[ApiController,Route("api/technician"),Authorize(Roles="Technician")]
public class TechnicianController(FIXITDbContext db,IWebHostEnvironment env) : ControllerBase
{
 string UserId=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
 async Task<TechnicianProfile?> Profile()=>await db.TechnicianProfiles.SingleOrDefaultAsync(x=>x.UserId==UserId);
 [HttpPut("application")] public async Task<IActionResult> Apply(TechnicianApplicationRequest r){var p=await Profile();if(p is null)return NotFound();if(p.Status is TechnicianStatus.Approved or TechnicianStatus.Suspended)return Conflict(new{message="Your application cannot be edited in its current state."});var serviceIds=r.ServiceIds.Distinct().ToArray();var areaIds=r.CoverageAreaIds.Distinct().ToArray();if(serviceIds.Length!=r.ServiceIds.Length||areaIds.Length!=r.CoverageAreaIds.Length)return BadRequest(new{message="Choose each service and coverage area once."});if(await db.Services.CountAsync(s=>serviceIds.Contains(s.Id)&&s.IsActive)!=serviceIds.Length)return BadRequest(new{message="Choose active FIXIT service categories."});var areas=await db.ServiceAreas.Where(a=>areaIds.Contains(a.Id)&&a.IsActive).ToListAsync();if(areas.Count!=areaIds.Length)return BadRequest(new{message="Choose active FIXIT coverage areas."});var oldSkills=await db.TechnicianSkills.Where(x=>x.TechnicianId==UserId).ToListAsync();var oldAreas=await db.TechnicianCoverageAreas.Where(x=>x.TechnicianId==UserId).ToListAsync();db.TechnicianSkills.RemoveRange(oldSkills);db.TechnicianCoverageAreas.RemoveRange(oldAreas);foreach(var serviceId in serviceIds)db.TechnicianSkills.Add(new(){TechnicianId=UserId,ServiceId=serviceId});foreach(var areaId in areaIds)db.TechnicianCoverageAreas.Add(new(){TechnicianId=UserId,ServiceAreaId=areaId});p.Skills=r.OtherSkills?.Trim()??"";p.CoverageAreas=string.Join(", ",areas.Select(x=>x.CityMunicipality));p.Status=TechnicianStatus.Pending;await db.SaveChangesAsync();return Ok(new{status=p.Status.ToString()});}
 [HttpGet("application")] public async Task<IActionResult> Application(){var p=await db.TechnicianProfiles.AsNoTracking().Where(x=>x.UserId==UserId).Select(x=>new{serviceIds=x.TechnicianSkills.Select(s=>s.ServiceId).ToList(),services=x.TechnicianSkills.Select(s=>s.Service.Name).ToList(),coverageAreaIds=x.TechnicianCoverageAreas.Select(a=>a.ServiceAreaId).ToList(),coverageAreas=x.TechnicianCoverageAreas.Select(a=>a.ServiceArea.CityMunicipality+", "+a.ServiceArea.Province).ToList(),otherSkills=x.Skills,status=x.Status.ToString(),x.DecisionReason,x.ReviewedAt}).SingleOrDefaultAsync();return p is null?NotFound():Ok(p);}
 [HttpGet("verification")] public async Task<IActionResult> Verification()=>Ok(await db.VerificationRecords.AsNoTracking().Where(x=>x.TechnicianId==UserId).OrderByDescending(x=>x.SubmittedAt).Select(x=>new{x.Id,x.DocumentType,status=x.Status.ToString(),x.DecisionReason,x.SubmittedAt,x.ReviewedAt}).ToListAsync());
 [HttpPost("verification"),RequestSizeLimit(6_000_000)] public async Task<IActionResult> SubmitVerification(IFormFile file,[FromForm]string documentType){if(string.IsNullOrWhiteSpace(documentType)||documentType.Length>60)return BadRequest(new{message="Enter a document type."});if(file.Length is 0 or >5_000_000)return BadRequest(new{message="Choose a file smaller than 5 MB."});var header=new byte[8];await using(var input=file.OpenReadStream())await input.ReadExactlyAsync(header);var pdf=header.AsSpan(0,5).SequenceEqual("%PDF-"u8);var png=header.AsSpan().StartsWith(new byte[]{137,80,78,71,13,10,26,10});var jpg=header[0]==0xff&&header[1]==0xd8&&header[2]==0xff;if(!pdf&&!png&&!jpg)return BadRequest(new{message="Only PDF, JPEG, and PNG verification files are accepted."});var folder=Path.Combine(env.ContentRootPath,"PrivateUploads");Directory.CreateDirectory(folder);var key=Guid.NewGuid().ToString("N")+(pdf?".pdf":jpg?".jpg":".png");await using(var output=new FileStream(Path.Combine(folder,key),FileMode.CreateNew,FileAccess.Write,FileShare.None))await file.CopyToAsync(output);var record=new VerificationRecord{TechnicianId=UserId,DocumentType=documentType.Trim(),PrivateStorageKey=key};db.VerificationRecords.Add(record);await db.SaveChangesAsync();return Accepted(new{id=record.Id,status=record.Status.ToString()});}
 [HttpPut("availability")] public async Task<IActionResult> Availability([FromQuery]bool online){var p=await Profile();if(p is null)return NotFound();if(p.Status!=TechnicianStatus.Approved&&online)return Forbid();p.IsOnline=online;await db.SaveChangesAsync();return Ok(new{p.IsOnline});}
 [HttpGet("availability/schedule")] public async Task<IActionResult> Schedule()=>Ok(await db.TechnicianAvailabilities.AsNoTracking().Where(x=>x.TechnicianId==UserId).OrderBy(x=>x.DayOfWeek).Select(x=>new{x.DayOfWeek,x.StartTime,x.EndTime,x.IsAvailable}).ToListAsync());
 [HttpPut("availability/schedule")] public async Task<IActionResult> Schedule([FromBody]AvailabilitySlotRequest[] slots){if(slots.GroupBy(x=>x.DayOfWeek).Any(g=>g.Count()>1)||slots.Any(x=>x.StartTime>=x.EndTime))return BadRequest(new{message="Add one valid availability range per weekday."});var existing=await db.TechnicianAvailabilities.Where(x=>x.TechnicianId==UserId).ToListAsync();db.TechnicianAvailabilities.RemoveRange(existing);foreach(var slot in slots)db.TechnicianAvailabilities.Add(new(){TechnicianId=UserId,DayOfWeek=slot.DayOfWeek,StartTime=slot.StartTime,EndTime=slot.EndTime,IsAvailable=slot.IsAvailable});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("jobs")] public async Task<IActionResult> Jobs(){var p=await Profile();if(p?.Status!=TechnicianStatus.Approved||!p.IsOnline)return Ok(Array.Empty<object>());return Ok(await db.Bookings.AsNoTracking().Where(b=>b.TechnicianId==null&&b.Status==BookingStatus.Pending&&db.TechnicianSkills.Any(s=>s.TechnicianId==UserId&&s.ServiceId==b.ServiceId)&&db.TechnicianCoverageAreas.Any(a=>a.TechnicianId==UserId&&a.ServiceArea.IsActive&&a.ServiceArea.CityMunicipality==b.Address.CityMunicipality&&a.ServiceArea.Province==b.Address.Province)&&!db.TechnicianJobDeclines.Any(d=>d.BookingId==b.Id&&d.TechnicianId==UserId)&&db.TechnicianAvailabilities.Any(a=>a.TechnicianId==UserId&&a.IsAvailable&&a.DayOfWeek==(int)b.ScheduledAt.AddHours(8).DayOfWeek&&a.StartTime<=TimeOnly.FromDateTime(b.ScheduledAt.AddHours(8))&&a.EndTime>=TimeOnly.FromDateTime(b.ScheduledAt.AddHours(8)))&&!db.Bookings.Any(x=>x.TechnicianId==UserId&&x.Status!=BookingStatus.Cancelled&&x.ScheduledAt>=b.ScheduledAt.AddHours(-2)&&x.ScheduledAt<=b.ScheduledAt.AddHours(2))).OrderBy(b=>b.ScheduledAt).Select(b=>new{id=b.Id,b.Reference,b.ProblemDescription,b.ScheduledAt,service=b.Service.Name,b.EstimatedTotal,city=b.Address.CityMunicipality,province=b.Address.Province}).ToListAsync());}
 [HttpGet("jobs/mine")] public async Task<IActionResult> Mine()=>Ok(await db.Bookings.AsNoTracking().Where(b=>b.TechnicianId==UserId).OrderBy(b=>b.ScheduledAt).Select(b=>new{id=b.Id,b.Reference,b.ProblemDescription,b.ScheduledAt,status=b.Status.ToString(),b.EstimatedTotal,b.CompletionNotes,b.PartsUsed,service=b.Service.Name,customer=new{b.Customer.FirstName,b.Customer.LastName,b.Customer.PhoneNumber},address=new{b.Address.Street,b.Address.Barangay,b.Address.CityMunicipality,b.Address.Province,b.Address.Region,b.Address.Landmark}}).ToListAsync());
 [HttpPost("jobs/{id:int}/accept")] public async Task<IActionResult> Accept(int id){var p=await Profile();if(p?.Status!=TechnicianStatus.Approved||!p.IsOnline)return Forbid();await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var b=await db.Bookings.Include(x=>x.Address).SingleOrDefaultAsync(x=>x.Id==id);if(b is null)return NotFound();if(b.Status!=BookingStatus.Pending||b.TechnicianId is not null||!await db.TechnicianCoverageAreas.AnyAsync(a=>a.TechnicianId==UserId&&a.ServiceArea.IsActive&&a.ServiceArea.CityMunicipality==b.Address.CityMunicipality&&a.ServiceArea.Province==b.Address.Province)||!await db.TechnicianSkills.AnyAsync(s=>s.TechnicianId==UserId&&s.ServiceId==b.ServiceId))return Conflict(new{message="This booking is no longer available for your selected services or coverage."});var local=b.ScheduledAt.AddHours(8);var time=TimeOnly.FromDateTime(local);if(!await db.TechnicianAvailabilities.AnyAsync(a=>a.TechnicianId==UserId&&a.IsAvailable&&a.DayOfWeek==(int)local.DayOfWeek&&a.StartTime<=time&&a.EndTime>=time))return Conflict(new{message="Your availability does not include this appointment."});var from=b.ScheduledAt.AddHours(-2);var to=b.ScheduledAt.AddHours(2);if(await db.Bookings.AnyAsync(x=>x.TechnicianId==UserId&&x.Status!=BookingStatus.Cancelled&&x.ScheduledAt>=from&&x.ScheduledAt<=to))return Conflict(new{message="You have another job near this time."});b.TechnicianId=UserId;b.Status=BookingStatus.Accepted;db.BookingAssignments.Add(new(){BookingId=id,TechnicianId=UserId,AssignedById=UserId});db.BookingStatusHistories.Add(new(){BookingId=id,Status=b.Status,ChangedByUserId=UserId,Note="Accepted by technician"});db.Notifications.Add(new(){UserId=b.CustomerId,Title="Technician accepted your booking",Message=$"A FIXIT technician accepted booking {b.Reference}."});await db.SaveChangesAsync();await tx.CommitAsync();return Ok(new{b.Reference,status=b.Status.ToString()});}
 [HttpPost("jobs/{id:int}/pass")] public async Task<IActionResult> Pass(int id,JobDeclineRequest request){var p=await Profile();if(p?.Status!=TechnicianStatus.Approved||!p.IsOnline)return Forbid();var b=await db.Bookings.Include(x=>x.Address).SingleOrDefaultAsync(x=>x.Id==id);if(b is null)return NotFound();if(b.Status!=BookingStatus.Pending||b.TechnicianId is not null||!await db.TechnicianCoverageAreas.AnyAsync(a=>a.TechnicianId==UserId&&a.ServiceArea.IsActive&&a.ServiceArea.CityMunicipality==b.Address.CityMunicipality&&a.ServiceArea.Province==b.Address.Province)||!await db.TechnicianSkills.AnyAsync(s=>s.TechnicianId==UserId&&s.ServiceId==b.ServiceId))return Conflict(new{message="This offer is no longer available for your selected services or coverage."});var local=b.ScheduledAt.AddHours(8);var time=TimeOnly.FromDateTime(local);if(!await db.TechnicianAvailabilities.AnyAsync(a=>a.TechnicianId==UserId&&a.IsAvailable&&a.DayOfWeek==(int)local.DayOfWeek&&a.StartTime<=time&&a.EndTime>=time))return Conflict(new{message="This booking is not in your current availability."});var decline=await db.TechnicianJobDeclines.SingleOrDefaultAsync(x=>x.BookingId==id&&x.TechnicianId==UserId);if(decline is null)db.TechnicianJobDeclines.Add(new(){BookingId=id,TechnicianId=UserId,Reason=request.Reason?.Trim()});else{decline.Reason=request.Reason?.Trim();decline.CreatedAt=DateTime.UtcNow;}await db.SaveChangesAsync();return NoContent();}
 [HttpPut("jobs/{id:int}/work-report")] public async Task<IActionResult> WorkReport(int id,WorkReportRequest r){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.TechnicianId==UserId);if(b is null)return NotFound();if(b.Status!=BookingStatus.InProgress)return Conflict(new{message="Repair reports can be saved while work is in progress."});b.CompletionNotes=r.CompletionNotes.Trim();b.PartsUsed=r.PartsUsed?.Trim();db.BookingStatusHistories.Add(new(){BookingId=id,Status=b.Status,ChangedByUserId=UserId,Note="Technician saved repair notes and parts used"});db.Notifications.Add(new(){UserId=b.CustomerId,Title="Repair report updated",Message=$"The technician updated the repair report for booking {b.Reference}."});await db.SaveChangesAsync();return Ok(new{b.CompletionNotes,b.PartsUsed});}
 [HttpPut("jobs/{id:int}/status")] public async Task<IActionResult> Status(int id,StatusRequest r){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.TechnicianId==UserId);if(b is null)return NotFound();if(!BookingWorkflow.CanTransition(b.Status,r.Status)||r.Status is BookingStatus.Accepted or BookingStatus.Cancelled or BookingStatus.Disputed or BookingStatus.Completed)return Conflict(new{message="That job status transition is not allowed."});if(r.Status==BookingStatus.WorkCompleted&&string.IsNullOrWhiteSpace(b.CompletionNotes))return Conflict(new{message="Save the repair notes before marking work complete."});b.Status=r.Status;db.BookingStatusHistories.Add(new(){BookingId=id,Status=r.Status,ChangedByUserId=UserId,Note=r.Note?.Trim()});db.Notifications.Add(new(){UserId=b.CustomerId,Title="Booking progress updated",Message=$"Booking {b.Reference} status: {r.Status}. {r.Note}"});await db.SaveChangesAsync();return Ok(new{status=b.Status.ToString()});}
 [HttpPost("jobs/{id:int}/additional-work")] public async Task<IActionResult> Propose(int id,AdditionalWorkRequestBody r){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.TechnicianId==UserId&&x.Status==BookingStatus.InProgress);if(b is null)return NotFound();var w=new AdditionalWorkRequest{BookingId=id,TechnicianId=UserId,Description=r.Description.Trim(),Amount=r.Amount};db.AdditionalWorkRequests.Add(w);db.BookingStatusHistories.Add(new(){BookingId=id,Status=b.Status,ChangedByUserId=UserId,Note="Additional work and charge proposed; customer approval required"});db.Notifications.Add(new(){UserId=b.CustomerId,Title="Additional work needs your approval",Message=$"A technician proposed additional work for booking {b.Reference}. Review the description and charge before approving."});await db.SaveChangesAsync();return Accepted(new{id=w.Id,status=w.Status.ToString()});}
 [HttpPost("jobs/{id:int}/disputes")] public async Task<IActionResult> Dispute(int id,DisputeRequest r){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==id&&x.TechnicianId==UserId);if(b is null)return NotFound();if(b.Status is BookingStatus.Cancelled or BookingStatus.Disputed)return Conflict();b.Status=BookingStatus.Disputed;db.Disputes.Add(new(){BookingId=id,ReportedById=UserId,Description=r.Description.Trim()});db.BookingStatusHistories.Add(new(){BookingId=id,Status=b.Status,ChangedByUserId=UserId,Note="Technician opened a dispute"});await db.SaveChangesAsync();return Accepted();}
 [HttpGet("earnings")]
 public async Task<IActionResult> Earnings()
 {
     var jobs=await db.Bookings.AsNoTracking().Where(b=>b.TechnicianId==UserId&&b.Status==BookingStatus.Completed)
         .OrderByDescending(b=>b.ScheduledAt)
         .Select(b=>new{b.Reference,b.EstimatedTotal,created=b.ScheduledAt,payment=db.Payments.Where(p=>p.BookingId==b.Id).Select(p=>new{status=p.Status.ToString(),p.Amount,p.PlatformFeePercent,p.PlatformFeeAmount,p.TechnicianEarnings,p.PaidAt}).FirstOrDefault()})
         .ToListAsync();
     var paid=jobs.Where(x=>x.payment?.status==PaymentStatus.Paid.ToString()).ToList();
     return Ok(new{completedJobs=jobs.Count,paidJobs=paid.Count,gross=paid.Sum(x=>x.payment!.Amount),platformFee=paid.Sum(x=>x.payment!.PlatformFeeAmount),earnings=paid.Sum(x=>x.payment!.TechnicianEarnings),jobs});
 }
 [HttpGet("reviews")] public async Task<IActionResult> Reviews(){var reviews=await db.Reviews.AsNoTracking().Where(r=>r.Booking.TechnicianId==UserId&&r.State==ReviewState.Visible).OrderByDescending(r=>r.CreatedAt).Select(r=>new{r.Rating,r.Comment,r.CreatedAt,booking=r.Booking.Reference,service=r.Booking.Service.Name}).ToListAsync();return Ok(new{count=reviews.Count,average=reviews.Count==0?0:Math.Round(reviews.Average(x=>x.Rating),2),reviews});}
}
